    emptied["hash"] = ""
    emptied["prev_hash"] = ""
    return json.dumps(
        emptied, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash: str, line: dict[str, Any]) -> str:
    payload = (prev_hash + "|" + canonical_bytes(line).decode("utf-8")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

